package uz.plugin.ogg_record_player;

/**
 * The API Dart calls through JNI (bindings in `lib/src/bindings/ogg_record_player_api.g.dart`, generated by
 * `dart run tool/jnigen.dart`). Kept in Java with only primitive, String and byte[] types so JNIgen can read it
 * from source without building the app; every call goes to the engine's {@code OggRecordPlayerHost}.
 *
 * <p>Results and failures come back through callbacks, failures as the shared {@code PlayerError} codes. Calls
 * made while no engine is attached answer {@code UNKNOWN} or do nothing.
 */
public final class OggRecordPlayerApi {
    private OggRecordPlayerApi() {}

    /** State changes of every player; {@code errorCode} is set only for state 4 (failed). */
    public interface PlayerListener {
        void onStateChanged(int playerId, int state, double position, double duration, double speed, String errorCode);
    }

    /** Recorder results, the same events and payloads as the former `onRecorder*` channel callbacks. */
    public interface RecorderListener {
        void onCanceled(int recorderId, int reason);

        void onStartFailed(int recorderId, String error);

        void onFinished(int recorderId, long durationMillis, byte[] waveform);
    }

    /** Answers one `createFrom*` call. */
    public interface CreateCallback {
        void onCreated(int playerId);

        void onFailed(String code, String message, String details);
    }

    /** {@code known} is false when the duration is unavailable; {@code seconds} is then meaningless. */
    public interface DurationCallback {
        void onDuration(boolean known, double seconds);
    }

    public interface DoneCallback {
        void onDone();
    }

    /** Replaces the listeners of the current engine; a hot restart registers new ones. */
    public static void setListeners(PlayerListener playerListener, RecorderListener recorderListener) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host != null) host.setListeners(playerListener, recorderListener);
    }

    public static void createFromFile(String path, CreateCallback callback) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host == null) detached(callback);
        else host.createFromFile(path, callback);
    }

    public static void createFromUrl(String url, CreateCallback callback) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host == null) detached(callback);
        else host.createFromUrl(url, callback);
    }

    public static void createFromBytes(byte[] bytes, CreateCallback callback) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host == null) detached(callback);
        else host.createFromBytes(bytes, callback);
    }

    public static void warmUp(DoneCallback callback) {
        OggRecordPlayerHost.Companion.warmUp(callback);
    }

    public static void play(int playerId) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host != null) host.play(playerId);
    }

    public static void pause(int playerId) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host != null) host.pause(playerId);
    }

    /** Stops and releases the player; its id is invalid afterwards. */
    public static void stop(int playerId) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host != null) host.stop(playerId);
    }

    public static void getDuration(int playerId, DurationCallback callback) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host == null) callback.onDuration(false, 0);
        else host.getDuration(playerId, callback);
    }

    public static void setPlaybackSpeed(int playerId, double speed) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host != null) host.setPlaybackSpeed(playerId, speed);
    }

    /** Returns the recorder id, or -1 when {@code path} is empty or no engine is attached. */
    public static int createRecorder(String path) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        return host == null ? -1 : host.createRecorder(path);
    }

    /** Returns null once the recording was started, else an `OggOpusRecorderException` code. */
    public static String startRecord(int recorderId) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        return host == null ? "UNKNOWN" : host.startRecord(recorderId);
    }

    public static void stopRecord(int recorderId) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host != null) host.stopRecord(recorderId);
    }

    public static void destroyRecorder(int recorderId) {
        OggRecordPlayerHost host = OggRecordPlayerHost.Companion.getCurrent();
        if (host != null) host.destroyRecorder(recorderId);
    }

    private static void detached(CreateCallback callback) {
        callback.onFailed("UNKNOWN", "Failed to create player", "no Flutter engine is attached");
    }
}
